function track(c,rec,old){const tr=E[c].track||[];rec.history=(old&&old.history?old.history.slice(-59):[]);
 if(!old)rec.history.push({at:now(),by:S.me,f:'created'});
 else for(const k of tr)if(JSON.stringify(old[k]??'')!==JSON.stringify(rec[k]??''))rec.history.push({at:now(),by:S.me,f:k,from:old[k]??'',to:rec[k]??'',note:rec._note||''});
 if(rec.stage&&(old?old.stage!==rec.stage:!rec.stageAt))rec.stageAt=now();delete rec._note}
