/* ---------- business rules ---------- */
const norm={phone:v=>String(v||'').replace(/[^\d+]/g,'').replace(/^00/,'+').replace(/^\+/,''),email:v=>String(v||'').trim().toLowerCase()};
const reached=(r,st,order)=>order.indexOf(r.stage)>=order.indexOf(st)&&order.includes(r.stage)||(r.history||[]).some(h=>h.f==='stage'&&(h.to===st||h.from===st));
function check(c,r,old){const e=[];const need=(ok,en,ar)=>{if(!ok)e.push([en,ar])};
 if(c==='contacts'){r.phoneN=norm.phone(r.phone);r.emailN=norm.email(r.email);need(r.phone||r.email,'Add a phone number or an email address.','أضف رقم هاتف أو بريداً إلكترونياً.');
  if(!r._dupOk){const d=list('contacts').find(x=>x.id!==r.id&&!x.mergedInto&&((r.phoneN&&x.phoneN===r.phoneN)||(r.emailN&&x.emailN===r.emailN)));
   if(d){e.push(['Possible duplicate of '+d.name+'. Save again to keep both, or open the existing contact.','قد يكون مكرراً مع '+d.name+'. احفظ مرة أخرى للإبقاء على الاثنين أو افتح جهة الاتصال الموجودة.']);r._dupOk=1;r.dupOf=d.id}}}
 if(c==='inquiries'){const i=INQ.indexOf(r.stage);
  if(!r.responseDue&&r.receivedAt)r.responseDue=new Date(+new Date(r.receivedAt)+cfg().respMin*6e4).toISOString();
  if(i>=1)need(r.agent,'Assign an agent before moving past New.','أسنِد وكيلاً قبل تجاوز مرحلة جديد.');
  if(i>=3)need(r.firstResponseAt,'Record the first human response time before Connected.','سجّل وقت أول رد بشري قبل مرحلة تم التواصل.');
  if(r.stage==='qualified'){need(r.intent&&r.reqConfirmed,'Qualified needs a confirmed intent and confirmed requirements.','التأهيل يتطلب غرضاً مؤكداً ومتطلبات مؤكدة.');need(r.budgetMax||r.locations,'Qualified needs a budget or preferred locations.','التأهيل يتطلب ميزانية أو مواقع مفضلة.');need(r.agent,'Qualified needs a responsible agent.','التأهيل يتطلب وكيلاً مسؤولاً.');need(r.nextAction&&r.nextDue,'Qualified needs a next action and its due date.','التأهيل يتطلب إجراءً تالياً وموعده.')}
  if(INQ_ALT.includes(r.stage))need(r.reason,'Record a reason for this outcome.','سجّل سبب هذه النتيجة.')}
 if(c==='opportunities'){if(!OPP[r.otype||'sale'].includes(r.stage)&&!OPP_ALT.includes(r.stage))e.push(['This stage does not belong to the selected pipeline.','هذه المرحلة لا تنتمي إلى المسار المحدد.']);
  if(oppActive(r))need(r.owner&&r.nextAction&&r.nextDue,'An active deal needs an owner, a next action and a due date.','الصفقة النشطة تحتاج مسؤولاً وإجراءً تالياً وموعداً.');
  if(['lost','cancelled','expired','nurture'].includes(r.stage))need(r.reason,'Record a reason for this outcome.','سجّل سبب هذه النتيجة.');
  const idx=OPP[r.otype||'sale'].indexOf(r.stage);
  if(idx>=3&&idx<6)need(list('viewings').some(v=>v.opportunity===r.id)||list('offers').some(o=>o.opportunity===r.id),'Record a viewing or an offer for this deal before this stage.','سجّل معاينة أو عرضاً مالياً لهذه الصفقة قبل هذه المرحلة.');
  if(r.stage==='won')need(list('transactions').some(x=>x.opportunity===r.id&&x.contractSignedAt&&x.evidence),'Closed won needs a transaction with a signed contract date and closing evidence.','الإغلاق الناجح يتطلب معاملة بتاريخ توقيع العقد ودليل الإغلاق.')}
 if(c==='listings'){if(['approved','published'].includes(r.status))need(r.verifiedAt&&r.factSource,'Approval and publication need a verification date and the source of facts.','الاعتماد والنشر يتطلبان تاريخ التحقق ومصدر البيانات.');
  if(r.status==='published'){const p=get('properties',r.property)||{};need(p.availability==='available','Only available stock can be published.','لا يُنشر إلا المخزون المتاح.')}}
 if(c==='properties'){if(r.lat!==''||r.lng!=='')need(r.lat!==''&&r.lng!==''&&Math.abs(+r.lat)<=90&&Math.abs(+r.lng)<=180,'Enter both latitude and longitude, or leave both empty and place the property from the Map.','أدخل خط العرض وخط الطول معاً، أو اتركهما فارغين وحدّد الموقع من الخريطة.');if(old&&old.authority==='controlled'&&r.authority==='controlled'&&old.availability!==r.availability&&!r._lock)e.push(['Change the availability of a controlled unit with the Hold, Reserve and Release buttons on its record.','غيّر توفر الوحدة الخاضعة للسيطرة باستخدام أزرار الحجز والإفراج في سجلها.']);
  if(r.authority==='third')need(r.availVerifiedAt&&r.availSource,'Third-party stock needs who reported the availability and when it was verified.','مخزون الطرف الثالث يتطلب مصدر إفادة التوفر ووقت التحقق.')}
 if(c==='viewings'){if(r.status==='completed')need(r.attendance&&r.feedback,'A completed viewing needs the attendance outcome and feedback.','المعاينة المكتملة تتطلب نتيجة الحضور والملاحظات.')}
 if(c==='offers'){if(['submitted','countered','accepted'].includes(r.ostatus)){need(r.listing&&r.amount&&r.currency&&r.terms&&r.party,'A submitted offer needs the property, amount, currency, terms and submitting party.','العرض المقدَّم يتطلب العقار والمبلغ والعملة والشروط والطرف المقدِّم.');need(['approved','not_required'].includes(r.approval),'A submitted offer needs its approval decided.','العرض المقدَّم يتطلب البتّ في اعتماده.')}
  if(r.approval==='approved'&&(!old||old.approval!=='approved'))need(['manager','admin'].includes(role()),'Only a sales manager approves offers.','اعتماد العروض من صلاحية مدير المبيعات فقط.')}
 if(c==='fees'){if(r.financeApproval==='approved'&&(!old||old.financeApproval!=='approved'))need(['finance','admin'].includes(role()),'Only finance approves commissions.','اعتماد العمولات من صلاحية المالية فقط.');
  if(['payable','paid'].includes(r.cstatus))need(r.eligible&&r.financeApproval==='approved','Commission becomes payable only when eligibility is met and finance has approved.','لا تصبح العمولة مستحقة إلا بتحقق الشروط واعتماد المالية.');
  if(r.cstatus==='reversed'||Number(r.adjustment))need(r.adjNote,'Record the reason for the adjustment or reversal.','سجّل سبب التسوية أو العكس.')}
 if(c==='transactions'){if(r.status==='closed')need(r.contractSignedAt&&r.evidence,'Closing needs the contract date and closing evidence.','الإغلاق يتطلب تاريخ العقد ودليل الإغلاق.')}
 return e}
async function after(c,r,old){
 if(c==='activities'&&r.direction==='outbound'&&r.channel!=='note'){for(const i of list('inquiries').filter(x=>x.contact===r.contact&&!x.firstResponseAt&&(!r.inquiry||x.id===r.inquiry)))await put('inquiries',Object.assign({},i,{firstResponseAt:r.at}))}
 if(c==='tasks'&&r.status==='done'&&old&&old.status!=='done'&&r.recur&&r.recur!=='none'){const d=new Date(r.due);if(r.recur==='daily')d.setDate(d.getDate()+1);if(r.recur==='weekly')d.setDate(d.getDate()+7);if(r.recur==='monthly')d.setMonth(d.getMonth()+1);
  const{id,history,createdAt,...b}=r;await put('tasks',Object.assign(b,{status:'open',due:d.toISOString()}))}
 if(c==='properties'&&old&&old.availability==='available'&&r.availability!=='available'){for(const l of list('listings').filter(x=>x.property===r.id&&x.status==='published'))await put('listings',Object.assign({},l,{status:'paused',_note:'stock unavailable'}))}}
/* controlled availability: checked and changed under a short lease so two people cannot take the same unit */
async function setAvail(pid,to,opp){const TAB=setAvail.tab=setAvail.tab||uid('tab');let cur=get('properties',pid);
 if(db){try{const ref=db.doc('properties/'+pid);const l=await ref.acquire({holder:TAB,ttlMs:8000});if(!l.acquired)return toast(t(['Someone else is changing this unit right now. Try again in a moment.','يقوم مستخدم آخر بتعديل هذه الوحدة الآن. حاول بعد لحظات.']));
  const s=await ref.get();if(s.exists)cur=Object.assign({id:pid},s.data())}catch(e){return toast(t(['Could not reach the unit record. Nothing changed.','تعذّر الوصول إلى سجل الوحدة. لم يتغير شيء.']))}}
 const a=cur.availability,ok=(to==='held'&&a==='available')||(to==='reserved'&&(a==='available'||(a==='held'&&(!cur.holdFor||cur.holdFor===opp||['manager','admin'].includes(role())))))||(to==='available'&&['held','reserved'].includes(a))||(['sold','leased'].includes(to)&&a==='reserved');
 if(!ok)return toast(t(['This unit is now '+ol(a)+'. The change was not applied.','هذه الوحدة الآن '+ol(a)+'. لم يُطبَّق التغيير.']));
 const r=Object.assign({},cur,{availability:to,_lock:1,availVerifiedAt:now(),availSource:(meRec()||{}).name||'Aisha'});delete r._lock;
 if(to==='held'){r.holdFor=opp||'';r.holdBy=S.me;r.holdUntil=new Date(Date.now()+cfg().holdHours*36e5).toISOString()}
 if(to==='reserved'){r.holdFor=opp||cur.holdFor||'';r.holdUntil=''}
 if(to==='available'){r.holdFor='';r.holdBy='';r.holdUntil=''}
 const old=get('properties',pid);await put('properties',r);await after('properties',r,old);toast(t(['Unit is now ','الوحدة الآن '])+ol(to))}

