 L.polygon(mp(BASE.world),o(land)).addTo(MAP);L.polygon(mp(BASE.land),o(land)).addTo(MAP);
 L.polygon(mp(BASE.urban),o({stroke:false,fillColor:'#e2e2e2',fillOpacity:1})).addTo(MAP);
 L.polygon(mp(BASE.lakes),o({stroke:false,fillColor:'#d9e0e4',fillOpacity:1})).addTo(MAP);
 L.polyline(BASE.rivers,o({color:'#b9c6cd',weight:1.6})).addTo(MAP);
