 const rows=lqf(k==='all'?R:R.filter(r=>(r.kind||'person')===k),r=>r.name+' '+(r.phone||'')+' '+(r.email||'')+' '+norm.phone(r.phone)).slice().sort((a,b)=>a.name.localeCompare(b.name));
